def home_jsonld():
 data={"@context":"https://schema.org","@graph":[{"@type":"MovingCompany","name":"CODEM Déménagements","telephone":["+33171361838","+33667570912"],"address":{"@type":"PostalAddress","streetAddress":"39 boulevard de Strasbourg","postalCode":"94130","addressLocality":"Nogent-sur-Marne","addressCountry":"FR"},"areaServed":["Paris","Île-de-France","France","Europe"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday"],"opens":"09:00","closes":"18:00"},{"@type":"OpeningHoursSpecification","dayOfWeek":"Friday","opens":"09:00","closes":"17:00"}],"knowsLanguage":["fr","en","es","pt"]},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":q,"acceptedAnswer":{"@type":"Answer","text":a}} for q,a in FAQ_DATA()]}]}
 return '<script type="application/ld+json">'+json.dumps(data,ensure_ascii=False)+'</script>'

def write(key,body,desc=None,head=''):
 p=OUT/url(key).lstrip('/');p.mkdir(parents=True,exist_ok=True);(p/'index.html').write_text(shell(key,body,desc,head))
if __name__=='__main__':
 import build as _self
 for LANG in ['fr','en']:
  _self.LANG=LANG;write('home',home(),None,home_jsonld()+__import__('faq').jsonld())
 (OUT/'index.html').write_text((OUT/'fr/index.html').read_text())
